// Scans src/app for page.tsx/page.ts files and writes the resulting static
// route paths to src/lib/generated/static-routes.ts.
//
// Why a generated file instead of scanning the filesystem inside sitemap.ts
// directly: this project deploys to Cloudflare Workers via OpenNext, and
// sitemap.ts revalidates on a schedule (ISR). On Cloudflare, an ISR
// revalidation re-invokes the route's code *inside the deployed Worker*,
// which has no access to the original src/app source tree the way a local
// `fs.readdirSync` call would expect. Scanning once here, at build time in a
// normal Node.js environment, and emitting a plain data file keeps the
// sitemap free of any runtime filesystem dependency, so it works the same
// whether it's served fresh after `next build` or re-validated later on
// Cloudflare.
//
// Runs automatically via the "prebuild" / "precf:build" npm scripts, so a
// newly added page.tsx is picked up on the next build with no manual edits
// to sitemap.ts.

import { readdirSync, statSync, writeFileSync, mkdirSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const APP_DIR = path.join(__dirname, "..", "src", "app");
const OUTPUT_FILE = path.join(__dirname, "..", "src", "lib", "generated", "static-routes.ts");

const PAGE_FILENAMES = new Set(["page.tsx", "page.ts", "page.jsx", "page.js"]);

function isDynamicSegment(segment) {
  return segment.startsWith("[");
}

function isRouteGroup(segment) {
  return segment.startsWith("(") && segment.endsWith(")");
}

function isPrivateFolder(segment) {
  return segment.startsWith("_");
}

// Walks a directory, returning the list of static (non-dynamic) route paths
// found beneath it. `urlSegments` accumulates the URL path so far.
function walk(dir, urlSegments, underDynamicSegment) {
  const entries = readdirSync(dir);
  const routes = [];

  if (!underDynamicSegment && entries.some((entry) => PAGE_FILENAMES.has(entry))) {
    const url = "/" + urlSegments.join("/");
    routes.push(url === "/" ? "/" : url.replace(/\/+/g, "/"));
  }

  for (const entry of entries) {
    if (entry === "api" || isPrivateFolder(entry)) continue;

    const fullPath = path.join(dir, entry);
    if (!statSync(fullPath).isDirectory()) continue;

    if (isRouteGroup(entry)) {
      // Route groups don't appear in the URL, but we still need to know if
      // anything under them is itself dynamic.
      routes.push(...walk(fullPath, urlSegments, underDynamicSegment));
      continue;
    }

    const nextUnderDynamic = underDynamicSegment || isDynamicSegment(entry);
    routes.push(...walk(fullPath, [...urlSegments, entry], nextUnderDynamic));
  }

  return routes;
}

const routes = walk(APP_DIR, [], false).sort();

mkdirSync(path.dirname(OUTPUT_FILE), { recursive: true });
writeFileSync(
  OUTPUT_FILE,
  `// AUTO-GENERATED by scripts/generate-static-routes.mjs — do not edit by hand.
// Regenerated automatically before every build (see "prebuild" / "precf:build"
// in package.json). Dynamic routes (e.g. /projects/[slug]) are intentionally
// excluded here; they're sourced from live data in src/app/sitemap.ts instead.

export const STATIC_ROUTES: string[] = ${JSON.stringify(routes, null, 2)};
`
);

console.log(`Generated ${routes.length} static route(s) -> ${path.relative(process.cwd(), OUTPUT_FILE)}`);
routes.forEach((route) => console.log(`  ${route}`));
